                          {state.holidays.length > 5 && (
                              <span className="bg-slate-800 border border-slate-700 text-slate-400 text-[10px] md:text-xs px-2 py-1 rounded-md">
                                  +{state.holidays.length - 5} more
                              </span>
                          )}
                      </div>
                  )}
               </div>
            </div>
          </div>
        </motion.div>

        {/* Analytics Section */}
